        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §1</em> <small>(c. 350 AD)</small><p>&#x27;In the beginning was the Word, and the Word was with God, and the Word was God&#x27; — Athanasius marks Jn 1:1 as the Johannine PROEM that the entire De Incarnatione exposits. The triad of predicates is irreducible: ēn (was — eternal continuous-existence, not egeneto came-to-be); pros ton theon (with God — relationally-distinct from the Father); theos ēn (was God — ontologically-identical-essence with the Father). The triad names the eternal-Word&#x27;s eternal-existence + eternal-distinction + eternal-divinity in one breath. Athanasius&#x27;s anti-Arian polemic stands or falls on this verse: the Word never came-to-be (no &#x27;there was a time when he was not&#x27; — the Arian-slogan ēn pote hote ouk ēn is the exact contradiction of ēn here). Tewahedo Logos-theology cites Jn 1:1 + Heb 1:1-3 + Col 1:15-17 as the irreducible-Logos-triad of biblical-Christology.</p></aside>',
