    (
        1,
        14,
        "i",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;The Word became flesh&#x27; is, for Cyril, the dogmatic foundation of the Miaphysite confession received by Tewahedo: one incarnate nature of the Word, indivisibly united from two natures (divine and human) without confusion. Against the Nestorian reading that finds two persons or two natures-after-union, Cyril insists the union is hypostatic and indivisible. The Tewahedo Synaxarium honors Cyril on the 3rd of Hamlē for this defense.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk I.14 (NPNF S2 V14, Pusey/Randell trans., Oxford 1874-1885) + Second Letter to Nestorius. PD.",
    ),
    (
        1,
        14,
        "j",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>De Incarnatione Verbi §8</em> <small>(c. 350 AD)</small><p>&#x27;And the Word was made flesh, and dwelt among us, (and we beheld his glory, the glory as of the only begotten of the Father,) full of grace and truth&#x27; — Athanasius marks ho Logos sarx egeneto (the Word became flesh) as the SINGLE most important verse for the entire incarnational-treatise. The egeneto (became) is genuine becoming — not Docetic-appearing, not Arian-creature-clothing, not Nestorian-association-with. The Word remained-what-he-was (eternal-divine-Logos) and BECAME-what-he-was-not (genuine-human-sarx). The eskēnōsen (dwelt — literally &#x27;tabernacled&#x27;) connects to the OT shekinah-dwelling and to Jn 2:21 (&#x27;he spake of the temple of his body&#x27;). The doxan-as-of-monogenous (glory-of-only-begotten) is the visible-Shekinah-glory of the incarnate-Word that Peter, James, John see at the Transfiguration (Mt 17:1-8, 2 Pet 1:16-18). This is Athanasius&#x27;s signature-verse: DI §54&#x27;s famous &#x27;He was made man that we might be made God&#x27; is the soteriological-corollary of Jn 1:14&#x27;s incarnational-fact. The Tewahedo Lǝdat-creed cites Jn 1:14 first among the Johannine prologue verses.</p></aside>',
        "Athanasius of Alexandria, De Incarnatione Verbi (On the Incarnation), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 25 (1857).",
    ),
