    (
        1,
        18,
        "f",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;No man hath seen God at any time; the only-begotten Son, who is in the bosom of the Father, He hath declared Him&#x27; is for Cyril the dogmatic statement of the Son&#x27;s unique revelatory office. &#x27;In the bosom of the Father&#x27; (eis ton kolpon tou Patros) Cyril reads not spatially but as expressing intimate co-substantiality and eternal mutual indwelling. The Son&#x27;s revelation is not derivative testimony but the Father&#x27;s self-disclosure in His own Word. Against Eunomian rationalism (which claimed direct knowledge of the divine essence), Cyril here grounds Christian epistemology in the Son&#x27;s mediation: we know the Father only through the Son who eternally knows Him.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk I.18 (NPNF S2 V14). PD.",
    ),
