    (
        1,
        23,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>On John the Baptist&#x27;s self-identification as &#x27;the voice of one crying in the wilderness&#x27; (citing Isa 40:3), Cyril develops the patristic distinction between Voice (phone) and Word (logos): the Baptist is the audible preparation for the eternal Word&#x27;s manifestation. The Voice is heard, then ceases; the Word abides forever. The &#x27;wilderness&#x27; Cyril reads typologically: not merely the Judean desert but the spiritual barrenness of pre-Incarnational humanity awaiting the Word&#x27;s coming. The Tewahedo Synaxarium honors the Baptist as the &#x27;lamp of Christ&#x27; on the 30th of Hidar, preserving this Voice-Word distinction in its liturgical hymnody.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.23 (NPNF S2 V14). PD.",
    ),
