    (
        1,
        29,
        "g",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;Behold the Lamb of God, which taketh away the sin of the world&#x27; Cyril reads as the typological climax of the entire Hebrew sacrificial economy: the Paschal lamb of Exodus, the lambs of the daily burnt offering, the Isaianic lamb led to the slaughter — all converge in the Baptist&#x27;s pointing finger. The &#x27;taketh away&#x27; (airon) Cyril stresses as present-tense ongoing action: the Lamb&#x27;s atoning work is not a single historical moment but the perpetual offering perpetually applied through the Church&#x27;s eucharistic representation. This sacrificial-eucharistic reading is foundational to the Tewahedo Anaphora&#x27;s offertory prayers.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.29 (NPNF S2 V14). PD.",
    ),
