    (
        3,
        8,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>On &#x27;The wind bloweth where it listeth&#x27; Cyril makes the most of the Greek pneuma&#x27;s double sense (wind / spirit): the meteorological observation grounds the pneumatological doctrine. The Spirit&#x27;s working in regeneration is sovereign (chooses its own subjects), audible-in-effects (the voice is heard), but invisible-in-cause (we cannot trace its origin or destination). Against Pelagian readings that would make human will the operative cause of regeneration, Cyril insists the Spirit&#x27;s freedom is primary: regeneration is sovereign gift, even where it is mediated through baptism&#x27;s prescribed channels. The Spirit who fills the prescribed channels is not bound by them.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.8 (NPNF S2 V14). PD.",
    ),
