    (
        3,
        14,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>Christ&#x27;s typological self-reference — &#x27;as Moses lifted up the serpent in the wilderness, even so must the Son of man be lifted up&#x27; — Cyril develops with characteristic typological care. The bronze serpent was a likeness of the agent of death (the serpent) elevated as the means of healing; Christ on the cross is the likeness of sinful flesh (Rom 8:3) elevated as the means of salvation. The &#x27;must&#x27; (dei) Cyril reads as expressing not external necessity (the schemes of His enemies) but the Father&#x27;s eternal redemptive will to which the Son freely conforms. The Tewahedo Holy Week liturgy preserves this typological reading prominently.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.14 (NPNF S2 V14). PD.",
    ),
