    (
        5,
        8,
        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>Christ&#x27;s command to the paralytic — &#x27;Rise, take up thy bed, and walk&#x27; — Cyril reads as the threefold pattern of every healing the Word performs in the soul: resurrection from spiritual death (rise), taking up the burden of one&#x27;s former weakness as instrument rather than master (take up thy bed), and active progress in the new life (walk). The thirty-eight years of paralysis Cyril typologically links with the thirty-eight years of Israel&#x27;s wilderness wandering (Deut 2:14) — both the individual and the people are healed by direct sovereign address, not by mediating ceremony or stirred-pool waiting. The Sabbath setting prepares Cyril&#x27;s larger argument: Christ exercises the Father&#x27;s authority over the Sabbath because He is consubstantial with the Father.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.8 (NPNF S2 V14). PD.",
    ),
