    (
        5,
        19,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;The Son can do nothing of Himself, but what He seeth the Father do&#x27; Cyril reads with extreme care against Arian misreading. The &#x27;can do nothing of Himself&#x27; is NOT a statement of weakness or subordination but of perfect Trinitarian harmony: the Son&#x27;s operations are inseparable from the Father&#x27;s because of their consubstantial unity. The &#x27;seeing&#x27; is not perceptual observation (as if the Son had to watch what the Father did) but eternal mutual indwelling of co-equal Persons. &#x27;What things soever He doeth, these also doeth the Son likewise&#x27; (homoiōs) Cyril stresses: not subordinately, not differently, but identically — every divine work belongs to all three Persons indivisibly.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.19 (NPNF S2 V14). PD.",
    ),
