    (
        5,
        21,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;As the Father raiseth up the dead, and quickeneth them; even so the Son quickeneth whom He will&#x27; — Cyril takes the absolute power of the eschatological resurrection as the supreme proof of consubstantiality. To raise the dead is a work exclusively divine; for the Son to share this power without limit means He shares the divine nature. &#x27;Whom He will&#x27; (hous thelei) Cyril emphasizes: not a delegated authority to be exercised within constraints, but sovereign personal choice — the same will that the Father exercises. The verse also establishes the personalist character of resurrection: Christ raises individuals by His sovereign decision, not as automatic effect of cosmic process.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.21 (NPNF S2 V14). PD.",
    ),
