    (
        5,
        22,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;The Father judgeth no man, but hath committed all judgment unto the Son&#x27; Cyril reads as the eschatological consummation of the Father-Son economy: the Father&#x27;s universal judgment is exercised through the incarnate Son, who because of His shared human nature is uniquely fit to judge humanity. The &#x27;committed&#x27; (dedōken) Cyril carefully distinguishes from any subordinationist reading: this is not a delegation of authority the Father lacks the will to exercise directly, but the manifestation of the eternal Trinitarian order — every operation &#x27;from the Father, through the Son, in the Spirit&#x27; (Cyril&#x27;s standard formula). This verse grounds Cyril&#x27;s later argument (in the Twelve Anathemas) that the man-God Christ, not a separate human judge, presides at the Last Day.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.22 (NPNF S2 V14). PD.",
    ),
