    (
        5,
        24,
        "f",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;He that heareth my word, and believeth on Him that sent me, HATH everlasting life&#x27; Cyril reads as one of the strongest realized-eschatology pins in the Gospel: eternal life is not merely promised for the future but present possession of the believer through faith. &#x27;Is passed from death unto life&#x27; (metabebēken — perfect tense, completed action with continuing result) confirms the present reality: the believer has ALREADY transitioned from the death-realm to the life-realm. This is not denial of future bodily resurrection (which Cyril affirms strongly) but recognition that the spiritual-ontological transition has already occurred for those united to Christ by faith. The verse grounds Cyril&#x27;s sacramental realism: baptism enacts what faith receives.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk II.24 (NPNF S2 V14). PD.",
    ),
