    (
        6,
        35,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;I am the bread of life&#x27; (egō eimi ho artos tēs zōēs) — the first of Christ&#x27;s great &#x27;I AM&#x27; sayings in John — Cyril reads as both ontological self-disclosure and sacramental promise. The &#x27;I am&#x27; echoes the divine name (Ex 3:14: ego eimi ho ōn); the &#x27;bread of life&#x27; identifies the specific mode of Christ&#x27;s gift to His Church. &#x27;He that cometh to me shall never hunger, and he that believeth on me shall never thirst&#x27; Cyril takes as the perfect parallel between coming-to-Christ (sacramentally: through baptism into His body) and believing-on-Him (fiducially: through saving faith) — neither alone, but both together produce the perpetual satisfaction of spiritual hunger and thirst.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk III.35 (NPNF S2 V14). PD.",
    ),
