    (
        7,
        24,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;Judge not according to the appearance (kat&#x27; opsin), but judge righteous judgment&#x27; Cyril reads as Christ&#x27;s hermeneutical principle for theological discernment. The Jews were judging based on surface considerations (the Sabbath violation appeared); Christ calls them to deeper judgment (the inner meaning of the law as service to humanity). For Cyril this verse is the dominical warrant for the typological-spiritual exegesis of the Old Testament: the appearance of the text (the literal-historical sense) must be supplemented by the righteous judgment (the spiritual-Christological sense) that recognizes Christ in every passage. This grounds the entire Alexandrian hermeneutical method.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk IV.24 (NPNF S2 V14). PD.",
    ),
