    (
        7,
        38,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;He that believeth on me, as the scripture hath said, out of his belly (koilias) shall flow rivers of living water&#x27; Cyril reads as the pneumatological promise: the Spirit indwelling the believer becomes a perpetual source overflowing to others. The &#x27;rivers&#x27; (plural — potamoi) signify both abundance (not merely a trickle) and diversity (different charisms flowing through different believers). The &#x27;belly&#x27; (koilias) Cyril interprets as the heart in its biblical-Hebraic sense — the seat of personal life — not the digestive organ. The Tewahedo baptismal liturgy preserves this verse as one of the dominical promises connected to the chrismation that immediately follows baptism: the Spirit poured out becomes the believer&#x27;s own source of life-giving witness to others.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk V.38 (NPNF S2 V14). PD.",
    ),
