    (
        11,
        35,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>The shortest verse in the Gospel — &#x27;Jesus wept&#x27; (edakrysen ho Iēsous) — Cyril expounds at length as decisive for orthodox Christology against three errors at once. (1) Against the Apollinarian denial of Christ&#x27;s true human soul (Christ wept with real human grief, possessing human affections). (2) Against the Docetist denial of true incarnation (the tears were real tears, not theatrical). (3) Against any Stoic reading of impassibility-applied-to-Christ (Christ&#x27;s incarnate nature genuinely felt sorrow). Yet Cyril carefully preserves the divine nature&#x27;s impassibility: the WEEPING is predicated of the one Person via the assumed humanity, not of the divine essence in itself. This is Miaphysite Christology applied to a single verse — load-bearing for Tewahedo dogmatic theology.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk VII.35 (NPNF S2 V14). PD.",
    ),
