        '<strong>Cross-references.</strong> <a href="#vnote-jhn-3-14">Jhn 3:14</a> · <a href="#vnote-jhn-8-28">Jhn 8:28</a>. <em>[Reviewer: select 1–3 most relevant; rewrite as a thematic note rather than a list before promoting.]</em>',
