    (
        12,
        32,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;And I, if I be lifted up (hypsōthō) from the earth, will draw all men unto me&#x27; Cyril unpacks the deliberate double sense of &#x27;lifted up&#x27;: it refers at once to the cross (literal elevation on the wood) AND to glorification (exaltation to the Father&#x27;s right hand) — the two are one redemptive movement in John&#x27;s theology. &#x27;Draw all men&#x27; (pantas helkysō) Cyril reads as universal scope of the saving intention: not only Jews, not only those present, but all humanity drawn by the magnetic power of the crucified-and-glorified Word. John&#x27;s parenthetical note (v. 33: &#x27;this He said, signifying what death He should die&#x27;) is Cyril&#x27;s textual confirmation that the cross is integral to the drawing.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk VIII.32 (NPNF S2 V14). PD.",
    ),
