        "<strong>Topics.</strong> This verse appears under: JESUS, JUDAS, CONCERNING THE MESSIAH, MISCELLANEOUS, IN THE NEW TESTAMENT FROM. <em>[Reviewer: pick one topic (typically the first or most theologically loaded), write a 2–3 sentence thematic note, and discard the rest.]</em>",
