    (
        13,
        18,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;He that eateth bread with me hath lifted up his heel against me&#x27; (citing Ps 41:9) Cyril reads as Christ&#x27;s authoritative prophetic self-application of the Psalter. The verse establishes simultaneously: (1) Christ&#x27;s foreknowledge of Judas&#x27;s betrayal (refuting any reading that the cross was reactive surprise); (2) Christ&#x27;s deliberate inclusion of Judas at the Supper (Judas receives the bread before going out — Cyril notes the eucharistic implications, though carefully); and (3) the messianic-prophetic reading of the Psalms as testimony to Christ (the Psalter&#x27;s &#x27;I&#x27; is appropriated by the messianic &#x27;I&#x27;). The Tewahedo liturgical Psalter reads Psalm 41 with explicit Christological cross-reference per Cyril&#x27;s pattern.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk IX.18 (NPNF S2 V14). PD.",
    ),
