    (
        13,
        34,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another&#x27; Cyril carefully expounds the &#x27;newness&#x27; (kainēn) which the Mosaic commandment to love neighbor (Lev 19:18) had not abrogated. The newness consists in the CHRISTOLOGICAL measure (&#x27;as I have loved you&#x27;) and in the new pneumatic capacity (the Spirit poured out makes possible what the law commanded). The &#x27;as I have loved&#x27; Cyril reads as the love-of-Christ-for-His-Church (extending to the cross) being the operative pattern; Christian love is participatory imitation, not autonomous achievement. This verse anchors Cyril&#x27;s ecclesiology: the Church is the community of those who love as Christ loved.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk IX.34 (NPNF S2 V14). PD.",
    ),
