    (
        14,
        1,
        "f",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;Let not your heart be troubled (mē tarassesthō): ye believe in God, believe also in me&#x27; Cyril notes the deliberate parallel of objects of faith: &#x27;believe in God&#x27; and &#x27;believe in me&#x27; (pisteuete eis ton Theon, kai eis eme pisteuete). The grammatical symmetry is Christological: faith in God and faith in Christ are not two different acts but one act with one object — the Triune God, in whose self-disclosure the Son is fully God. Against Arian readings that would distinguish &#x27;belief in God&#x27; (proper) from &#x27;belief in Christ&#x27; (subordinate), Cyril insists the parallel construction excludes any qualitative difference. The verse becomes a creedal pin for Tewahedo Trinitarian dogmatics.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk IX.1 (NPNF S2 V14). PD.",
    ),
