    (
        14,
        2,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;In my Father&#x27;s house are many mansions (monai pollai)&#x27; Cyril reads with characteristic eschatological precision. The &#x27;many&#x27; (pollai) Cyril takes as denying any uniform single eschatological reward: there are differentiated places-of-abiding corresponding to differentiated degrees of holiness attained. Yet he is careful against any Origenist universalism (which would make the differentiation purely educational on a unified upward path): the differentiation is permanent in the eschaton, not transitional. &#x27;Father&#x27;s house&#x27; Cyril reads as the totality of the kingdom, with the &#x27;mansions&#x27; (literally &#x27;abiding-places&#x27; — monai from menein, to remain) as the differentiated participation each saint has in the one beatific vision. This grounds the Tewahedo doctrine of the differentiated heavenly hierarchy of saints.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk IX.2 (NPNF S2 V14). PD.",
    ),
