    (
        14,
        6,
        "g",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;I am the way, the truth, and the life: no man cometh unto the Father, but by me&#x27; is for Cyril the most exhaustive single-verse Christological self-disclosure in the Gospel. Each of the three predicates (the Way, the Truth, the Life) is paired with its corresponding human-need: the Way (for those who wander), the Truth (for those who err), the Life (for those who die). &#x27;No man cometh unto the Father, but by me&#x27; Cyril takes as the textual root of Christological exclusivism: there is no Father-knowledge, no Father-relationship, no Father-presence available except through the Son. Against any reading that would permit alternative access (whether through other religions, through philosophical contemplation, or through natural ethics), Cyril insists on Johannine exclusivity. This verse anchors Tewahedo missiology.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk IX.6 (NPNF S2 V14). PD.",
    ),
