    (
        14,
        9,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;He that hath seen me hath seen the Father&#x27; Cyril carefully unpacks against both Sabellian and Arian misreadings. Against Sabellians who would collapse the Persons: the verse does NOT identify the Son AS the Father (Cyril notes the immediate sequel: &#x27;I am in the Father, and the Father in me&#x27; preserves the Personal distinction). Against Arians who would subordinate the Son: the verse asserts the Son&#x27;s perfect representational adequacy — to see Him IS to see the Father, not partially or by analogy but fully and by nature. Cyril notes that the seeing in question is theological perception (&#x27;he that hath seen&#x27; = he that has truly recognized in faith), not merely physical optics. The verse grounds the Tewahedo iconographic tradition&#x27;s confidence that depicting Christ&#x27;s face is legitimate.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk IX.9 (NPNF S2 V14). PD.",
    ),
    (
        14,
        9,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos III.1-3</em> <small>(c. 350 AD)</small><p>&#x27;Have I been so long time with you, and yet hast thou not known me, Philip? he that hath seen me hath seen the Father; and how sayest thou then, Shew us the Father?&#x27; — Athanasius marks heōraken ton patera (hath-seen the Father) as the visibility-claim that follows from Jn 10:30&#x27;s hen-esmen. To see the Son is to see the Father — not because Son and Father are the same-Person (modalism&#x27;s mistake) and not because the Son is merely-an-image-of-the-Father (Arianism&#x27;s mistake), but because the Son IS the eternal-eikōn-of-the-Father (Col 1:15) such that seeing the perfect-image is seeing the exact-substance the image perfectly reproduces. Athanasius pairs Jn 14:9 with Heb 1:3 (charaktēr tēs hypostaseōs autou — &#x27;the express-image of his person&#x27;) as the canonical-pair of perfect-eikōn-visibility verses. Tewahedo iconology cites Jn 14:9 as the Christological-warrant for the legitimacy of Christ-iconography (the Son&#x27;s incarnate-circumscribability makes the Father&#x27;s-eikōn depictable).</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
    ),
