    (
        15,
        1,
        "f",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;I am the true vine, and my Father is the husbandman&#x27; Cyril takes as the sixth of Christ&#x27;s &#x27;I AM&#x27; sayings and the foundational text for the doctrine of vital union between Christ and the Church. &#x27;True&#x27; (alēthinē) Cyril emphasizes against any merely metaphorical or typological reading: Christ is not LIKE a vine, He IS the vine in the substantive sense — the source of life for the branches grafted into Him. The Father as &#x27;husbandman&#x27; (geōrgos) Cyril reads as the Trinitarian operation in vine-tending: the Father&#x27;s pruning and cultivating work is exercised through the Son in the Spirit. The Tewahedo Anaphora preserves this vine-husbandman language in its ecclesiological prayers.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk X.1 (NPNF S2 V14). PD.",
    ),
