    (
        15,
        5,
        "d",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;I am the vine, ye are the branches: he that abideth in me, and I in him, the same bringeth forth much fruit: for without me ye can do nothing&#x27; is for Cyril the Christological-ecclesiological pin against any reading that would make Christian life autonomous. The reciprocal abiding (en emoi / en autō — in me / in him) Cyril takes as extending the Johannine perichoresis (14:10-11) from the Trinity to the Christ-Church relation by participation. &#x27;Without me ye can do nothing&#x27; (chōris emou ou dynasthe poiein ouden) Cyril takes with full force: not &#x27;less effectively&#x27; but &#x27;nothing at all&#x27; — every fruit-bearing in the Christian life is participatory in Christ&#x27;s own activity. The verse is the textual foundation for the Tewahedo doctrine of synergism-in-grace: human cooperation is real but always sourced in prior divine indwelling.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk X.5 (NPNF S2 V14). PD.",
    ),
