    (
        15,
        13,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;Greater love hath no man than this, that a man lay down his life for his friends&#x27; Cyril reads as Christ&#x27;s self-disclosure of the love that the cross will enact within hours. The &#x27;greater&#x27; (meizona) establishes the comparative absolute: no love exceeds self-laying-down-for-friends. Christ&#x27;s love for the world (Jn 3:16) is enacted as this love in the cross; the cross is therefore the visible measure of the previously-invisible Trinitarian love. &#x27;For his friends&#x27; (hyper tōn philōn autou) Cyril reads with care: the love is universal in offer (15:16 &#x27;I have chosen you&#x27;), particular in friendship-bond. This anticipates the eucharistic ethic that becomes determinative for the Tewahedo monastic-martyrological tradition: laying-down-of-life is the Christian&#x27;s proper response to having been thus loved.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk X.13 (NPNF S2 V14). PD.",
    ),
