    (
        15,
        26,
        "f",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;But when the Comforter is come, whom I will send unto you from the Father, even the Spirit of truth, which proceedeth from the Father, He shall testify of me&#x27; is THE pneumatological text Cyril cites most heavily in his Trinitarian theology. The Greek ekporeuetai (proceedeth) Cyril reads as the eternal procession of the Spirit from the Father (the Eastern Orthodox foundation for the original Nicene formulation, against the later Western Filioque). Yet &#x27;whom I will send&#x27; (pempsō egō) preserves the Son&#x27;s role in the temporal mission of the Spirit. Cyril distinguishes carefully: the ETERNAL procession is from-the-Father-alone; the TEMPORAL mission is through-the-Son. This distinction becomes determinative for Eastern + Oriental Orthodox pneumatology, including Tewahedo.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk X.26 (NPNF S2 V14). PD.",
    ),
    (
        15,
        27,
        "",
        "",
        "topic-nave",
        "Topic",
        "Topic.",
        "<strong>Topics.</strong> This verse appears under: APOSTLE, MINISTER, TESTIMONY. <em>[Reviewer: pick one topic (typically the first or most theologically loaded), write a 2–3 sentence thematic note, and discard the rest.]</em>",
        "Nave's Topical Bible, Orville J. Nave (1896). Public domain.",
    ),
    (
        15,
        27,
        "a",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;And ye also shall bear witness, because ye have been with me from the beginning&#x27; Cyril takes as the apostolic-foundation text grounding the historical-witness character of the Christian message. &#x27;From the beginning&#x27; (ap&#x27; archēs) Cyril reads as the public-ministry beginning (from the Baptist&#x27;s witness onward) — the apostles&#x27; qualification to bear witness rests on direct historical eyewitness, not on personal religious experience alone. This grounds the patristic-Tewahedo doctrine of apostolic succession: the Church&#x27;s authoritative teaching traces back through a continuous chain to the eyewitness apostles, who saw with their own eyes what they then proclaimed.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk X.27 (NPNF S2 V14). PD.",
    ),
