    (
        17,
        3,
        "h",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent&#x27; Cyril unpacks as the dominical definition of eternal life: not merely endless duration but cognitive-relational participation in the divine knowledge. The infinitive &#x27;might know&#x27; (ginōskōsi — continuous action) Cyril takes as denoting ongoing personal knowing, not single intellectual grasp. The pairing (the Father AS only true God AND Jesus Christ AS sent) Cyril carefully reads to preserve both monotheism (against pagan polytheism) and Christological inclusion in deity (against Arian subordination): both clauses together constitute the saving knowledge. This verse anchors the Tewahedo catechetical tradition&#x27;s definition of theosis as participation-by-knowing.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XI.3 (NPNF S2 V14). PD.",
    ),
