    (
        17,
        5,
        "e",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;And now, O Father, glorify thou me with thine own self with the glory which I had with thee before the world was&#x27; (para seautō tē doxē hē eichon pro tou ton kosmon einai para soi) is Cyril&#x27;s strongest single-verse text for the eternal pre-existence of the Son. &#x27;Before the world was&#x27; Cyril takes against any Arian reading: the Son had glory WITH the Father before creation existed — therefore the Son&#x27;s existence is not within creation&#x27;s scope but eternal, alongside the Father from the very beginning. &#x27;Thine own self&#x27; (para seautō) preserves the Personal distinction even within the consubstantial unity: the glory is shared between distinct Persons, not collapsed into Sabellian identity. This verse is among Cyril&#x27;s most-cited prooftexts in the Twelve Anathemas against Nestorius.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XI.5 (NPNF S2 V14). PD.",
    ),
