    (
        18,
        36,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;My kingdom is not of this world (ek tou kosmou toutou): if my kingdom were of this world, then would my servants fight, that I should not be delivered to the Jews: but now is my kingdom not from hence&#x27; Cyril takes as the dominical pin against any theocratic or revolutionary reading of Christ&#x27;s mission. The kingdom&#x27;s NOT-FROM-HENCE (ek — out of, sourced in) does not mean NOT-FOR-HERE: it means not deriving its character from this-world&#x27;s power structures (force, military conquest, political dominance). The kingdom IS for the world, but it operates by different means (suffering love, persuasive truth, sacramental presence). Cyril&#x27;s reading establishes the theological frame for the Tewahedo monastic tradition&#x27;s withdrawal-from-political-power as the proper kingdom-ethic, while still affirming the kingdom&#x27;s universal scope.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XI.36 (NPNF S2 V14). PD.",
    ),
