    (
        19,
        11,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>Christ&#x27;s reply to Pilate — &#x27;Thou couldest have no power at all against me, except it were given thee from above&#x27; — Cyril takes as the comprehensive doctrine of divine sovereignty over even the Passion&#x27;s executioners. Pilate&#x27;s authority is real (not denied) but derivative (not autonomous): every act of the powerful is bounded by divine permission. &#x27;Therefore he that delivered me unto thee hath the greater sin&#x27; (continuing the verse) Cyril takes as establishing graduated responsibility within the system: the Sanhedrin who delivered Christ to Pilate bear greater responsibility than Pilate, who merely executes their judgment within the bounds of his secondary authority. This nuanced reading shapes the Tewahedo Holy Week liturgy&#x27;s careful theological framing.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XII.11 (NPNF S2 V14). PD.",
    ),
