    (
        19,
        26,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>Christ&#x27;s words from the cross to His mother and the beloved disciple — &#x27;Woman, behold thy son! ... Behold thy mother!&#x27; — Cyril reads at multiple levels. Literally, Christ provides for Mary&#x27;s continued care after His death (the eldest son&#x27;s filial obligation discharged even from the cross). Typologically, Cyril takes Mary as figure of the Church and John as figure of every disciple: in establishing John as Mary&#x27;s son, Christ establishes the Church as the Mother of every believer + every believer as the Church&#x27;s son. The Tewahedo Marian veneration (which is particularly developed compared to other Christian traditions) draws its theological warrant from this Cyrilline reading.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XII.26 (NPNF S2 V14). PD.",
    ),
