    (
        19,
        34,
        "b",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>On the blood and water from Christ&#x27;s pierced side, Cyril reads sacramentally: the water signifies baptism, the blood signifies the eucharist, both flowing from the wound that is the source of the Church&#x27;s life. The Tewahedo liturgical tradition preserves this dual symbolism with particular emphasis in the Anaphora of Our Lord Jesus Christ; the wound is the Church&#x27;s font and table.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XII.19. NPNF Series 2, vol. 14. PD.",
    ),
