    (
        19,
        36,
        "c",
        "",
        "comm-ethiopian",
        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>John&#x27;s interpretive comment — &#x27;For these things were done, that the scripture should be fulfilled, A bone of him shall not be broken&#x27; (citing Ex 12:46 / Num 9:12 / Ps 34:20) — Cyril takes as decisive paschal typology. The Passover lamb&#x27;s prohibition on broken bones is fulfilled in the crucifixion&#x27;s NOT-broken-bones (against the standard practice of breaking the legs to hasten death — done to the two thieves but providentially omitted for Christ). Cyril reads this as the divine providential ordering of even the smallest details of the Passion to display the Christ-as-Paschal-Lamb typology. The Tewahedo Passover-Easter liturgical complex preserves this typological reading prominently in its hymnody.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XII.36 (NPNF S2 V14). PD.",
    ),
