        "Tewahedo — Cyril of Alexandria",
        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>The threefold question — &#x27;Simon, son of Jonas, lovest thou me more than these?&#x27; — Cyril reads as the deliberate counterpart to Peter&#x27;s threefold denial. Christ&#x27;s repetition is restorative, not accusatory: each affirmation of love undoes one denial. &#x27;More than these&#x27; (pleon toutōn) Cyril reads as referring to the other disciples (Peter had boasted in 13:37 that he would die for Christ even if all others fell away — Christ now tests the boast). The Greek verbal play (agapē / phileō) Cyril notes but treats with characteristic restraint: both verbs in John often function as synonyms; the deeper distinction is in the questioning-and-answering pattern itself, not in word-choice subtleties.</p></aside>',
        "Cyril of Alexandria, Commentary on John, Bk XII.15 (NPNF S2 V14). PD.",
