        "Cyril of Alexandria (428).",
        '<aside class="note-comm-ethiopian"><strong>Cyril of Alexandria</strong> <em>Commentary on the Gospel of John</em> <small>(c. 428 AD)</small><p>&#x27;Feed my sheep&#x27; (boske ta probata mou) — the third and culminating commission to Peter — Cyril takes as the dominical institution of the pastoral office. The shift from &#x27;lambs&#x27; (arnia, in v. 15) to &#x27;sheep&#x27; (probata, in v. 17) Cyril reads as moving from the inexperienced new converts to the mature flock — the entire spectrum of pastoral responsibility is committed to Peter and through him to every subsequent pastor. The repetition Cyril sees as marking the deliberate sacramental-commissioning weight: this is not casual exhortation but solemn appointment. The Tewahedo ordination of bishops and priests preserves this verse&#x27;s institutional weight in its consecration prayers.</p></aside>',
